/**
 * The instant before which an archive has used up the retention window. A row
 * archived at or before it has expired. Both the restore check and the sweep
 * read the window through here, so they cannot disagree about the boundary.
 */
export function retentionCutoff(retentionDays: number, now: Date): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - retentionDays * MS_PER_DAY));
}

/** True once an archived row has been in the trash for the whole window. */
export function isExpired(row: SoftDeletable, cutoff: IsoTimestamp): boolean {
  return row.archivedAt !== null && row.archivedAt <= cutoff;
}

export type RestoreRefusalReason =
  | "not_archived"
  | "expired"
  | "project_archived"
  | "quota";

const RESTORE_REFUSAL_MESSAGES: Readonly<Record<RestoreRefusalReason, string>> = {
  not_archived: "The issue is not archived.",
  expired: "The issue has passed its restore window.",
  project_archived: "The issue's project is archived.",
  quota: "The project has no room for another issue under the plan.",
};

/** A restore that the current state of the row rules out. Nothing is changed. */
export class RestoreRefusedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly reason: RestoreRefusalReason) {
    super(RESTORE_REFUSAL_MESSAGES[reason]);
    this.name = "RestoreRefusedError";
  }
}

