/**
 * Every archived issue of the org, in every project, whose retention window
 * closed at or before `cutoff`. Deliberately unpaged: the sweep has to reach all
 * of them, however many issues the workspace has.
 */
export async function listExpiredIssueIds(
  orgId: OrgId,
  cutoff: IsoTimestamp,
): Promise<readonly IssueId[]> {
  const rows = getDb()
    .select({ id: issues.id })
    .from(issues)
    .where(
      and(
        orgPredicate(issues.orgId, orgId),
        isNotNull(issues.archivedAt),
        lte(issues.archivedAt, cutoff),
      ),
    )
    .all();

  return rows.map((row) => row.id as IssueId);
}

/** What a purge removed, so the caller can settle the counters it feeds. */
export interface PurgedIssue {
  readonly commentIds: readonly CommentId[];
  /** Megabytes the attachments were counted for: each one rounded up on its own. */
  readonly storageMb: number;
}

const BYTES_PER_MB = 1024 * 1024;

/**
 * Hard-deletes one expired issue with its label links, comments and attachments,
 * all in one transaction. The expiry is checked again inside it, so an issue
 * restored after the sweep listed it is left alone. Returns null when nothing was
 * purged. Search documents and counters are the caller's to settle.
 */
export async function purgeExpiredIssue(
  orgId: OrgId,
  issueId: IssueId,
  cutoff: IsoTimestamp,
): Promise<PurgedIssue | null> {
  return getDb().transaction((tx) => {
    const expired = tx
      .select({ id: issues.id })
      .from(issues)
      .where(
