/**
 * Restoring an archived issue, and what the retention sweep does with the ones
 * whose restore window has closed.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { RestoreRefusedError, retentionCutoff } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import { runCleanupArchivedJob } from "@/server/jobs/cleanup-archived-job";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityService from "@/server/services/activity-service";
import * as attachmentService from "@/server/services/attachment-service";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue } from "@/types/issue";

const DAY_MS = 24 * 60 * 60 * 1000;
/** The growth plan's `retentionDays`; the tenants below all sit on it. */
const RETENTION_DAYS = 365;

let cleanup: () => void;
let tenant: Tenant;
const listeners: Unsubscribe[] = [];
const captures: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  tenant = await createTenant("restore", "growth");
  listeners.push(
    usageService.registerUsageListeners(),
    searchService.registerSearchListeners(),
    activityService.registerActivityListeners(),
  );
});

afterEach(() => {
  while (captures.length > 0) captures.pop()?.();
});

afterAll(() => {
  for (const off of listeners) off();
  cleanup();
});

/** Collects every payload published for one event type during a test. */
function capture<K extends keyof TaskflowEventMap>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  captures.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

/** Runs `work` with only `Date` moved forward, as if `days` had passed. */
async function daysLater<T>(days: number, work: () => Promise<T>): Promise<T> {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(Date.now() + days * DAY_MS);
  try {
    return await work();
  } finally {
    vi.useRealTimers();
  }
}

/** Runs the retention sweep as it would run `days` from now. */
function sweepAfter(days: number) {
  return runCleanupArchivedJob(new Date(Date.now() + days * DAY_MS));
}

async function createIn(
  orgTenant: Tenant,
  title: string,
  projectId = orgTenant.project.id,
): Promise<Issue> {
  return issueService.createIssue(
    orgTenant.actors.member,
    issueInput(orgTenant.org.id, projectId, { title }),
  );
}

describe("issueService.restoreIssue", () => {
  it("brings an archived issue back under its original number", async () => {
    const issue = await createIn(tenant, "Restorable zebra");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    const searchable = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "zebra",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(searchable.items.map((row) => row.subjectId)).not.toContain(issue.id);

    const usageBefore = await usageRepo.getUsage(tenant.org.id);
    const restoredEvents = capture("issue.restored");

    const restored = await issueService.restoreIssue(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );

    expect(restored.archivedAt).toBeNull();
    expect(restored.number).toBe(issue.number);
    expect(restoredEvents).toEqual([
      expect.objectContaining({
        issueId: issue.id,
        projectId: issue.projectId,
        actorId: tenant.userIds.member,
      }),
    ]);

    const usageAfter = await usageRepo.getUsage(tenant.org.id);
    expect(usageAfter.issuesUsed).toBe(usageBefore.issuesUsed + 1);

    const reindexed = await searchRepo.searchDocuments({
      orgId: tenant.org.id,
      q: "zebra",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(reindexed.items.map((row) => row.subjectId)).toContain(issue.id);

    const audit = await activityService.listActivity(tenant.actors.member, {
      orgId: tenant.org.id,
      action: ["issue.restored"],
      limit: 25,
      cursor: null,
    });
    expect(audit.items.map((event) => event.subjectId)).toContain(issue.id);
  });

  it("refuses an issue that is not archived, changing nothing", async () => {
    const issue = await createIn(tenant, "Still live");
    const restoredEvents = capture("issue.restored");

    const attempt = issueService.restoreIssue(
      tenant.actors.member,
      tenant.org.id,
      issue.id,
    );
    await expect(attempt).rejects.toBeInstanceOf(RestoreRefusedError);
    await expect(attempt).rejects.toMatchObject({
      reason: "not_archived",
      code: "conflict",
    });
    expect(restoredEvents).toHaveLength(0);
  });

  it("refuses once the retention window has closed, before the sweep runs", async () => {
    const issue = await createIn(tenant, "Too late");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    const restoredEvents = capture("issue.restored");

    await expect(
      daysLater(RETENTION_DAYS + 1, () =>
        issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
      ),
    ).rejects.toMatchObject({ reason: "expired" });

    const stillArchived = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(stillArchived?.archivedAt).not.toBeNull();
    expect(restoredEvents).toHaveLength(0);
  });

  it("still restores on the last day of the retention window", async () => {
    const issue = await createIn(tenant, "Just in time");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    const restored = await daysLater(RETENTION_DAYS - 1, () =>
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
    );

    expect(restored.archivedAt).toBeNull();
  });

  it("refuses while the issue's project is archived", async () => {
    const scratch = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Restore scratch",
      slug: "restore-scratch",
      key: "SCRR",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    const issue = await createIn(tenant, "Inside scratch", scratch.id);
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: scratch.id,
      archiveIssues: false,
    });

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).rejects.toMatchObject({ reason: "project_archived" });
  });

  it("refuses when the project has no room under its issue quota", async () => {
    const free = await createTenant("restore-quota", "free");
    for (let number = 1; number <= 99; number += 1) {
      await issueRepo.insertIssue(
        issueInput(free.org.id, free.project.id, { title: `Quota seed ${number}` }),
        free.userIds.member,
        number,
      );
    }
    const doomed = await issueRepo.insertIssue(
      issueInput(free.org.id, free.project.id, { title: "Quota archived" }),
      free.userIds.member,
      100,
    );
    await issueService.archiveIssue(free.actors.member, free.org.id, doomed.id);
    await createIn(free, "Fills the freed slot");

    await expect(
      issueService.restoreIssue(free.actors.member, free.org.id, doomed.id),
    ).rejects.toMatchObject({ reason: "quota" });
  });

  it("denies an actor without issue:archive, unless they own the issue", async () => {
    const issue = await createIn(tenant, "Viewer must not restore");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    await expect(
      issueService.restoreIssue(tenant.actors.viewer, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  it("refuses an organization outside the actor's tenant", async () => {
    const other = await createTenant("restore-other");
    const issue = await createIn(tenant, "Cross tenant");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);

    await expect(
      issueService.restoreIssue(tenant.actors.member, other.org.id, issue.id),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("reports an unknown issue as not found", async () => {
    await expect(
      issueService.restoreIssue(
        tenant.actors.member,
        tenant.org.id,
        "missing-issue" as IssueId,
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

describe("the retention sweep", () => {
  it("purges an expired issue with its labels, comments, attachments and search documents", async () => {
    const org = await createTenant("purge", "growth");
    const label = await labelRepo.insertLabel({
      orgId: org.org.id,
      name: "purge-label",
      color: "#ef4444",
      description: null,
    });
    const doomed = await issueService.createIssue(
      org.actors.member,
      { ...issueInput(org.org.id, org.project.id, { title: "Doomed quokka" }), labelIds: [label.id] },
    );
    await commentService.createComment(org.actors.member, {
      orgId: org.org.id,
      issueId: doomed.id,
      body: "quokka commentary",
      parentId: null,
      mentionedUserIds: [],
    });
    // 1.5 MB counts as 2 MB and 1 KB as 1 MB: each attachment rounds up on its own.
    await attachmentService.addAttachment(org.actors.member, {
      orgId: org.org.id,
      issueId: doomed.id,
      filename: "spec.pdf",
      contentType: "application/pdf",
      sizeBytes: 1_572_864,
    });
    await attachmentService.addAttachment(org.actors.member, {
      orgId: org.org.id,
      issueId: doomed.id,
      filename: "note.txt",
      contentType: "text/plain",
      sizeBytes: 1_024,
    });
    const keeper = await createIn(org, "Keeper");
    await attachmentService.addAttachment(org.actors.member, {
      orgId: org.org.id,
      issueId: keeper.id,
      filename: "keep.png",
      contentType: "image/png",
      sizeBytes: 524_288,
    });

    const beforeArchive = await usageRepo.getUsage(org.org.id);
    expect(beforeArchive.storageMbUsed).toBe(4);
    await issueService.archiveIssue(org.actors.member, org.org.id, doomed.id);
    const archived = await usageRepo.getUsage(org.org.id);

    const result = await sweepAfter(RETENTION_DAYS + 1);

    expect(result.failed).toBe(0);
    expect(await issueRepo.findIssueById(org.org.id, doomed.id)).toBeNull();
    expect(await commentRepo.listThread(org.org.id, doomed.id)).toEqual([]);
    expect(
      await attachmentService.listAttachments(org.actors.member, org.org.id, doomed.id),
    ).toEqual([]);
    expect(
      (await labelRepo.listLabelsForIssues(org.org.id, [doomed.id]))[doomed.id] ?? [],
    ).toEqual([]);

    const orphans = await searchRepo.searchDocuments({
      orgId: org.org.id,
      q: "quokka",
      kinds: ["issue", "comment"],
      limit: 25,
      cursor: null,
    });
    expect(orphans.items).toEqual([]);

    const afterSweep = await usageRepo.getUsage(org.org.id);
    expect(afterSweep.storageMbUsed).toBe(archived.storageMbUsed - 3);
    expect(afterSweep.issuesUsed).toBe(archived.issuesUsed);
    const recount = await usageRepo.recomputeUsage(org.org.id);
    expect(afterSweep.storageMbUsed).toBe(recount.storageMbUsed);

    expect(await issueRepo.findIssueById(org.org.id, keeper.id)).not.toBeNull();
  });

  it("purges every expired issue, not only the first page of them", async () => {
    const org = await createTenant("purge-many", "growth");
    const total = 130;
    for (let number = 1; number <= total; number += 1) {
      const issue = await issueRepo.insertIssue(
        issueInput(org.org.id, org.project.id, { title: `Bulk ${number}` }),
        org.userIds.member,
        number,
      );
      await issueRepo.archiveIssue(org.org.id, issue.id);
    }

    const result = await sweepAfter(RETENTION_DAYS + 1);

    expect(result.failed).toBe(0);
    expect(result.processed).toBeGreaterThanOrEqual(total);
    const remaining = await issueRepo.listIssues({
      orgId: org.org.id,
      limit: 25,
      cursor: null,
      includeArchived: true,
    });
    expect(remaining.total).toBe(0);
  });

  it("never reuses the number of a purged issue", async () => {
    const org = await createTenant("numbers", "growth");
    await createIn(org, "Kept number");
    const purged = await createIn(org, "Purged number");
    await issueService.archiveIssue(org.actors.member, org.org.id, purged.id);

    await sweepAfter(RETENTION_DAYS + 1);
    expect(await issueRepo.findIssueById(org.org.id, purged.id)).toBeNull();

    const next = await createIn(org, "After the purge");
    expect(next.number).toBe(purged.number + 1);
  });

  it("leaves alone an issue restored before the sweep reaches it", async () => {
    const issue = await createIn(tenant, "Saved in time");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    await issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id);

    await sweepAfter(RETENTION_DAYS + 1);

    const live = await issueRepo.findIssueById(tenant.org.id, issue.id);
    expect(live).not.toBeNull();
    expect(live?.archivedAt).toBeNull();
    // A purge handed a live issue is a no-op, not a deletion.
    await expect(
      issueRepo.purgeExpiredIssue(
        tenant.org.id,
        issue.id,
        retentionCutoff(RETENTION_DAYS, new Date(Date.now() + 400 * DAY_MS)),
      ),
    ).resolves.toBeNull();
  });

  it("makes a purged issue unrestorable", async () => {
    const issue = await createIn(tenant, "Gone for good");
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    await sweepAfter(RETENTION_DAYS + 1);

    await expect(
      issueService.restoreIssue(tenant.actors.member, tenant.org.id, issue.id),
    ).rejects.toBeInstanceOf(NotFoundError);
  });
});

