/**
 * Raises a project's issue-number high-water mark to `number`. It never lowers
 * the mark, so a number that was once handed out stays spent.
 */
function reserveIssueNumber(
  db: Pick<Db, "insert">,
  orgId: OrgId,
  projectId: ProjectId,
  number: number,
): void {
  db.insert(issueNumberSequences)
    .values({ orgId, projectId, lastNumber: number })
    .onConflictDoUpdate({
      target: issueNumberSequences.projectId,
      set: {
        lastNumber: sql`max(${issueNumberSequences.lastNumber}, ${number})`,
      },
    })
    .run();
}

/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones. A purged issue has no
 * row left, so the sequence remembers the highest number ever handed out.
 */

