/** What a purge removed, so the caller can settle the counters it feeds. */
export interface PurgedIssue {
  readonly commentIds: readonly CommentId[];
  /** Megabytes the attachments were counted for: each one rounded up on its own. */
  readonly storageMb: number;
}

const BYTES_PER_MB = 1024 * 1024;

/**
 * Hard-deletes one expired issue with its label links, comments and attachments,
 * all in one transaction. The expiry is checked again inside it, so an issue
 * restored after the sweep listed it is left alone. Returns null when nothing was
 * purged. Search documents and counters are the caller's to settle.
 */
export async function purgeExpiredIssue(
  orgId: OrgId,
  issueId: IssueId,
  cutoff: IsoTimestamp,
): Promise<PurgedIssue | null> {
  return getDb().transaction((tx) => {
    const expired = tx
      .select({ projectId: issues.projectId, number: issues.number })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, orgId),
          eq(issues.id, issueId),
          isNotNull(issues.archivedAt),
          lte(issues.archivedAt, cutoff),
        ),
      )
      .get();
    if (!expired) return null;

    // Recorded before the row goes, so the number stays spent even for issues
    // created before the sequence existed.
    reserveIssueNumber(tx, orgId, expired.projectId as ProjectId, expired.number);

    const commentRows = tx
      .select({ id: comments.id })
      .from(comments)
      .where(
        and(
          orgPredicate(comments.orgId, orgId),
          eq(comments.issueId, issueId),
        ),
      )
      .all();

    const attachmentRows = tx
      .select({ sizeBytes: attachments.sizeBytes })
      .from(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .all();

    tx.delete(attachments)
      .where(
        and(
          orgPredicate(attachments.orgId, orgId),
          eq(attachments.issueId, issueId),
        ),
      )
      .run();
    tx.delete(comments)
      .where(
        and(
          orgPredicate(comments.orgId, orgId),
          eq(comments.issueId, issueId),
        ),
      )
      .run();
    tx.delete(issueLabels)
      .where(
        and(
          orgPredicate(issueLabels.orgId, orgId),
          eq(issueLabels.issueId, issueId),
        ),
      )
      .run();
    tx.delete(issues)
      .where(
        and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)),
      )
      .run();

    return {
      commentIds: commentRows.map((row) => row.id as CommentId),
      storageMb: attachmentRows.reduce(
        (total, row) => total + Math.ceil(row.sizeBytes / BYTES_PER_MB),
        0,
      ),
    };
  });
}

/** Cascade behind `ProjectService.archiveProject`; returns the row count. */

